"""Checked exterior-ring fallback for two close original three-way junctions.

An absorbed short span can end before either standalone turning contact exists.
Construct those two exterior corners directly on the surviving source curves.
Never move a source control or alter a prescribed radius. The retained-corner
construction remains preferred whenever it succeeds.
"""
import bpy
from . import curved_junction_nodes as b,curved_port_nodes as ports
from .curved_network_ownership_nodes import _compare,_total
c=b.c


def contains_rectangle(g,wire,start,tangent,length,width,offset):
    """Certify a straight absorbed strip against a simple sampled boundary.

    A connected rectangle is inside a simple polygon if its centre is inside
    and the polygon boundary never enters its interior. Slab clipping checks
    entire boundary segments, not just sampled vertex membership. The caller
    separately proves the boundary is simple. Metre tolerance is 1e-5.
    """
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);count=c._count(g,wire)
    a=c._sub(c._vec(g,g.position()),start)
    q=c._vec(g,c._sample(g,wire,g.position(),g.math('MODULO',i+1.,count),'FLOAT_VECTOR'))
    z=c._sub(q,start);right=c._right(tangent)
    pa=[c._dot(a,tangent),c._dot(a,right)-offset]
    pb=[c._dot(z,tangent),c._dot(z,right)-offset]
    enter=0.;leave=1.;possible=1.;eps=1e-5
    for x,y,low,high in zip(pa,pb,(eps,-.5*width+eps),(length-eps,.5*width-eps)):
        delta=y-x;parallel=g.math('LESS_THAN',g.math('ABSOLUTE',delta),1e-10)
        u=(low-x)/delta;v=(high-x)/delta
        enter=g.math('MAXIMUM',enter,c.choose(g,parallel,-1e10,g.math('MINIMUM',u,v)))
        leave=g.math('MINIMUM',leave,c.choose(g,parallel,1e10,g.math('MAXIMUM',u,v)))
        possible=possible*c.choose(g,parallel,g.math('GREATER_THAN',x,low)*g.math('LESS_THAN',x,high),1.)
    crosses=possible*g.math('GREATER_THAN',leave,enter+1e-8)
    boundary_clear=g.math('LESS_THAN',c._stat(g,wire,crosses,'Sum'),.5)
    # Horizontal ray from the rectangle centre, in the strip's local frame.
    ya=g.math('GREATER_THAN',pa[1],0.);yb=g.math('GREATER_THAN',pb[1],0.)
    straddles=g.math('ABSOLUTE',ya-yb)
    xhit=pa[0]-pa[1]*(pb[0]-pa[0])/(pb[1]-pa[1])
    hits=c._stat(g,wire,straddles*g.math('GREATER_THAN',xhit,.5*length),'Sum')
    return boundary_clear*g.math('COMPARE',g.math('MODULO',hits,2.),1.)*g.math('GREATER_THAN',count,2.5)


def build(*,interpolation=False):
    name='Prochitecture Streets / Short span exterior ring v1'
    if interpolation:name+=' / Exact profile frames v1'
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for key in ('Sources','Mapping','Approaches','Junctions'):g.socket(key,'NodeSocketGeometry')
    for key in ('Site A','Site B','Internal Span'):g.socket(key,'NodeSocketInt')
    for key,value in (('Join Radius',.5),('Cell Size',.5),('Height Exaggeration',10.)):
        g.socket(key,'NodeSocketFloat',default=value)
    for key in ('Boundary','Inspection Boundary','Mouths','Corners','Approaches','Diagnostics'):
        g.socket(key,'NodeSocketGeometry','OUTPUT')
    for key in ('Valid','Inputs Valid','Joins Valid','Wire Valid'):g.socket(key,'NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    selected=[];internal=[];centres=[];valid=1.-g.math('COMPARE',inp.outputs['Site A'],inp.outputs['Site B'])
    valid=valid*g.math('GREATER_THAN',inp.outputs['Join Radius'],1e-6)
    for side in ('A','B'):
        site=c.V(g,inp.outputs['Site '+side]);sites=inp.outputs['Junctions']
        start=c._read(g,sites,'st_cj_range_start',site,'INT');count=c._read(g,sites,'st_cj_range_count',site,'INT')
        valid=valid*g.math('GREATER_THAN',site,-.5)*g.math('LESS_THAN',site,c._count(g,sites)-.5)
        valid=valid*g.math('COMPARE',count,3.)*g.math('GREATER_THAN',start,-.5)
        valid=valid*g.math('LESS_THAN',start+count,c._count(g,inp.outputs['Approaches'])+.5)
        rows=c._select(g,inp.outputs['Approaches'],g.math('GREATER_THAN',index,start-.5)*g.math('LESS_THAN',index,start+count-.5))
        jid=c._read(g,sites,'st_cj_junction_id',site,'INT')
        same_site=_compare(g,c.named(g,'st_cj_junction_id','INT'),jid)*_compare(g,c.named(g,'st_pp_junction_id','INT'),jid)
        valid=valid*c._stat(g,rows,same_site*g.math('COMPARE',c.named(g,'st_cj_order','INT'),index))
        match=g.math('COMPARE',c.named(g,'st_pp_span','INT'),inp.outputs['Internal Span'])
        valid=valid*g.math('COMPARE',c._stat(g,rows,match,'Sum'),1.)
        at=c._stat(g,rows,index*match,'Sum')
        inside=c._select(g,rows,match);internal.append(inside)
        # Cyclic boundary walk: take both surviving incidences after the link.
        ring=c._line(g,2);source=g.math('MODULO',at+1.+index,count)
        for attr,kind in [('st_pp_'+key,'INT') for key in ('span','reverse','street_id','section_id','junction_id','connector_id','kind')]+[
            ('st_cj_'+key,'FLOAT' if key in ('rise','datum','radius') else 'INT')
            for key in ('reverse','street_id','section_id','junction_id','connector_id','span_index','half','rise','datum','radius')]:
            ring=c._store(g,ring,attr,c._read(g,rows,attr,source,kind),kind)
        ring=c._store(g,ring,'st_cj_input_index',start+source,'INT')
        ring=c._store(g,ring,'_ce_side',0 if side=='A' else 1,'INT');selected.append(ring)
        call=g.node('GeometryNodeGroup');call.node_tree=ports.approach(interpolation=interpolation)
        for key,value in (('Sources',inp.outputs['Sources']),('Mapping',inp.outputs['Mapping']),('Approaches',inside),('Index',0)):
            g.bind(value,call.inputs[key])
        internal[-1]=(inside,call)
        centres.append(c._vec(g,c._jet(g,call.outputs['Geometry'],0.,0.)['Point']))
        valid=valid*c.V(g,call.outputs['Valid'])
        # A complete two-control original Street is mathematically straight.
        # Use that structural guarantee instead of testing cancellation-prone
        # float32 cubic coefficients, which can change after a tiny edit.
        path=call.outputs['Geometry']
        valid=valid*g.math('COMPARE',c._count(g,path),2.)
        valid=valid*g.math('COMPARE',c._read(g,inp.outputs['Mapping'],'st_ps_count',inp.outputs['Internal Span'],'INT'),2.)
    rows=b._join(g,*selected);rows=c._store(g,rows,'st_cj_order',index,'INT')
    valid=valid*c._stat(g,rows,_compare(g,_total(g,1,c.named(g,'st_pp_span','INT')),1))
    # This finite branch currently retains a common radius and full crowns.
    for key in ('radius','rise','datum'):
        v=c.named(g,'st_cj_'+key)
        valid=valid*g.math('LESS_THAN',c._stat(g,rows,v,'Max')-c._stat(g,rows,v,'Min'),1e-6)
    valid=valid*c._stat(g,rows,g.math('COMPARE',c.named(g,'st_cj_half','INT'),0.))
    a,aa=internal[0];bb,bcall=internal[1]
    valid=valid*g.math('COMPARE',c._read(g,a,'st_pp_reverse',0,'INT')+c._read(g,bb,'st_pp_reverse',0,'INT'),1.)
    for key,sign in (('Width',1.),('Offset',-1.)):
        valid=valid*g.math('LESS_THAN',g.math('ABSOLUTE',c.V(g,aa.outputs[key])-sign*c.V(g,bcall.outputs[key])),1e-6)
    # A long ordinary connecting street must not be swallowed by this branch.
    radius=c._read(g,rows,'st_cj_radius',0)
    for inside,_source in internal:
        for key in ('radius','rise','datum'):
            valid=valid*g.math('LESS_THAN',g.math('ABSOLUTE',c._read(g,inside,'st_cj_'+key,0)-c._read(g,rows,'st_cj_'+key,0)),1e-6)
        valid=valid*g.math('COMPARE',c._read(g,inside,'st_cj_half',0,'INT'),0.)
    valid=valid*g.math('LESS_THAN',aa.outputs['Length'],c.V(g,aa.outputs['Width'])+2.*radius)
    call=g.node('GeometryNodeGroup');call.node_tree=b.build(port_paths=True,regularize_mouths=True,continuations=True,displaced_endpoints=True,interpolation=interpolation)
    for key in ('Sources','Mapping','Cell Size','Height Exaggeration'):g.bind(inp.outputs[key],call.inputs[key])
    g.bind(rows,call.inputs['Approaches'])
    mouths=call.outputs['Mouths'];corners=call.outputs['Corners']
    expected=c.choose(g,c._read(g,rows,'_ce_side',index,'INT'),g.xyz(*centres[1]),g.xyz(*centres[0]),'VECTOR')
    distance=c._length(g,c._sub(c._vec(g,c.named(g,'st_cj_endpoint','FLOAT_VECTOR')),c._vec(g,expected)))
    valid=valid*c._stat(g,mouths,g.math('LESS_THAN',distance,1e-4))
    mouths=c._store(g,mouths,'st_cj_input_index',c._read(g,rows,'st_cj_input_index',index,'INT'),'INT')
    corners=c._store(g,corners,'st_pc_kind',0,'INT');corners=c._store(g,corners,'st_pc_valid',c.named(g,'st_cj_valid','BOOLEAN'),'BOOLEAN')
    tangent=c._vec(g,c._jet(g,aa.outputs['Geometry'],0.,0.)['Tangent'])
    footprint=contains_rectangle(g,call.outputs['Boundary'],centres[0],tangent,
        c.V(g,aa.outputs['Length']),c.V(g,aa.outputs['Width']),c.V(g,aa.outputs['Offset']))
    accepted=valid*c.V(g,call.outputs['Valid'])*footprint
    diagnostics=c._store(g,call.outputs['Diagnostics'],'absorbed_footprint_valid',footprint,'BOOLEAN')
    out=g.node('NodeGroupOutput')
    for key,value in (('Boundary',b._empty(g,call.outputs['Boundary'],accepted)),
        ('Inspection Boundary',call.outputs['Inspection Boundary']),('Mouths',mouths),('Corners',corners),
        ('Approaches',rows),('Diagnostics',diagnostics),('Valid',accepted),
        ('Inputs Valid',valid),('Joins Valid',call.outputs['Corners Valid']),('Wire Valid',call.outputs['Wire Valid'])):
        g.bind(value,out.inputs[key])
    return g.g
